import os,pathlib
def inspect(mon_data,osd_data):
    def mount(path,space):
        path=pathlib.Path(path).resolve();matches=[]
        for line in pathlib.Path('/proc/self/mountinfo').read_text().splitlines():
            left,right=line.split(' - ',1);fields=left.split();tail=right.split();target=pathlib.Path(fields[4])
            if path.is_relative_to(target):matches.append((len(str(target)),fields[4],tail[0],tail[1]))
        _,target,fs_type,source=max(matches)
        row=dict(target=target,source=source,fs_type=fs_type,device=path.stat().st_dev)
        if space:
            stat=os.statvfs(path);row.update(total_bytes=stat.f_blocks*stat.f_frsize,available_bytes=stat.f_bavail*stat.f_frsize)
        return row
    files=[p for p in (pathlib.Path(mon_data)/'store.db').rglob('*')if p.is_file()]
    return dict(mon_mount=mount(mon_data,True),osd_mount=mount(osd_data,False),mon_db_logical_bytes=sum(p.stat().st_size for p in files),mon_db_allocated_bytes=sum(p.stat().st_blocks*512 for p in files))
def recover(approved_pressure_file,compact):
    pathlib.Path(approved_pressure_file).unlink(missing_ok=True)
    compact()

